import{_ as e,o as a,c as r,a6 as d}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"精度阶梯:从「能跑」到「像素级正确」","description":"","frontmatter":{"title":"精度阶梯:从「能跑」到「像素级正确」"},"headers":[],"relativePath":"nes-emulator-course/12-accuracy-ladder.md","filePath":"nes-emulator-course/docs/12-accuracy-ladder.md"}'),o={name:"nes-emulator-course/12-accuracy-ladder.md"};function s(n,t,i,p,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="精度阶梯-从「能跑」到「像素级正确」" tabindex="-1">精度阶梯:从「能跑」到「像素级正确」 <a class="header-anchor" href="#精度阶梯-从「能跑」到「像素级正确」" aria-label="Permalink to &quot;精度阶梯:从「能跑」到「像素级正确」&quot;">​</a></h1><p>你的模拟器跑 NROM 游戏大体正常,直到某一天加载了一张新卡带:画面顶部在特定场合撕裂(精灵溢出的时序不对);某个游戏卡在开机画面一动不动(它在读 $4015 等声音芯片就绪,而你的 APU 根本不存在);换一张带 MMC1 的卡带直接花屏(bank 切换没有实现,程序读到的全是错的窗口)。每一种故障都在问同一个问题:你的模拟器站在精度阶梯的哪一级,而这张卡带需要哪一级?</p><p>这门课在帧时序一章埋了四张「失败的卡带」——vbl_set_time、nmi_control、suppression、left_clip。它们不是这门课的污点,是这门课最后的教具:每一张都精确地标出了指令级精度的天花板在哪。这一章把阶梯画完整,让你知道自己在哪、上面还有几级、每级要付出什么。</p><h2 id="四级台阶-四类现象" tabindex="-1">四级台阶,四类现象 <a class="header-anchor" href="#四级台阶-四类现象" aria-label="Permalink to &quot;四级台阶,四类现象&quot;">​</a></h2><p>模拟器的精度可以粗分为四级,每级能解释的现象、不能解释的现象都清清楚楚:</p><table tabindex="0"><thead><tr><th>级别</th><th>时间粒度</th><th>能解释</th><th>不能解释</th></tr></thead><tbody><tr><td>指令级(本课程)</td><td>一条指令</td><td>官方指令语义与周期、帧节奏、VBlank/NMI 次数、绝大多数 NROM 游戏</td><td>同一指令内部的时序竞争</td></tr><tr><td>扫描线级</td><td>一条扫描线</td><td>分屏滚动的视觉结果</td><td>行内中段的寄存器改写</td></tr><tr><td>点级</td><td>一个 dot</td><td>行内改写、精灵逐点合成、sprite 0 hit 的行为语义</td><td>与 CPU 读写同拍的仲裁</td></tr><tr><td>周期级</td><td>CPU/PPU/APU 周期交错</td><td>全部已知硬件行为,含竞态与 open bus</td><td>——(代价是性能与复杂度)</td></tr></tbody></table><p>本课程站在第一级:CPU 按指令结算,PPU 成批追赶。它通过了 nestest、instr_test、cpu_timing_test——<strong>指令语义与指令周期数全对</strong>;也通过了 vbl_basics 与 sprite hit 的 basics/flip——<strong>帧级与行为级语义对</strong>。失败的四张考的都是同一件事:某个标志在哪一个 dot 置位、CPU 的某次读恰好发生在哪个 dot。以 vbl_set_time 为例,它测量的是「vblank 标志置位后 CPU 最早能在哪个周期读到」,指令粒度天然差着一两条指令的误差;suppression 更苛刻,考「读 $2002 与标志置位同拍时,读到什么、NMI 是否被吞」——真机有明确仲裁,指令级模型里根本不存在「同拍」这个概念。</p><p>想爬上第三级,主循环要从「指令结算」改成「逐周期交错」:CPU 每个周期让一次步,PPU 走三个 dot,APU 走一步,读写发生在精确的周期上。这不是推倒重来——本课程的模块边界(Cpu/Ppu/Bus 各自独立、总线注入)原样保留,换的只是 <code>runFrame</code> 里那个循环的粒度。这也是把主循环写得那么短的回报。</p><h2 id="三个未实现的子系统" tabindex="-1">三个未实现的子系统 <a class="header-anchor" href="#三个未实现的子系统" aria-label="Permalink to &quot;三个未实现的子系统&quot;">​</a></h2><p><strong>APU(声音)</strong>。2A03 里与 6502 同居的声音芯片:两个方波、一个三角波、一个噪声、一个 DMC 采样通道。游戏的兼容性风险主要在两处:读 $4015 返回的状态(长度计数器、DMC 中断),某些游戏开机等待它;DMC 的 DMA 会偷 CPU 周期——不做 DMC,周期账永远差一点。实现路线:先做帧计数器与 $4015 状态(让等待的游戏通过),再逐通道合成波形,最后接 Web Audio 的采样缓冲。手柄那章的结论在这里复用:外设是协议,不是变量。</p><p><strong>映射器</strong>。NROM 之外的世界按「窗口怎么搬」分几大家族:UxROM(mapper 2)把 $C000 固定、$8000 窗口在 16K bank 间切换,写一次 PRG 就换一块,适合大关卡游戏;MMC1(mapper 1)带串行配置寄存器与可切换的 CHR bank,还有电池存档;MMC3(mapper 4)带扫描线中断,是分屏卷轴游戏的常客。实现方式与本课程的接缝一致:把 <code>bus.cartRead</code> 从一个函数变成一个带状态的映射器对象,写 $8000-$FFFF 时改写它的 bank 寄存器。第一个练手对象选 mapper 2,改动最小、收益立竿见影。</p><p><strong>其余的边角</strong>:非官方 opcode(nestest 的后半段,某些商业游戏确实使用,上一章测试按设计抛错的那批);open bus(读未映射地址应返回上次总线值,本课程简化为 0);精灵溢出标志的硬件 bug(真机会在特定 OAM 内容下误报);PPU 的 $2004 读时序与 OAM 损坏效应。每一项都有社区测试卡带,失败信息就是施工图。</p><h2 id="社区的测试卡带体系" tabindex="-1">社区的测试卡带体系 <a class="header-anchor" href="#社区的测试卡带体系" aria-label="Permalink to &quot;社区的测试卡带体系&quot;">​</a></h2><p>这门课的验证反复用到 nesdev 社区几十年积累的测试 ROM:CPU 类(nestest、instr_test、cpu_timing_test)、PPU 时序类(vbl_nmi 系列、sprite hit 系列)、总线类(oam 测试、dummy reads)。把它们当单元测试用——跑一次、看屏幕/状态字节、修、再跑——是最有效率的精度爬升方式。本课程的 <code>verify/</code> 目录里留了运行脚本,你随时可以拿自己的模拟器对它们复跑。</p><p>一个实用的心态建议:<strong>按游戏驱动,不按完美驱动</strong>。你想跑的那张卡带需要什么,就实现什么、用什么测试卡带验收;「像素级正确」是无限游戏,「让这张卡带完美运行」是有限且可完成的目标。</p><h2 id="全课总结" tabindex="-1">全课总结 <a class="header-anchor" href="#全课总结" aria-label="Permalink to &quot;全课总结&quot;">​</a></h2><p>十二站走完,你拥有的是:一个能解析任意 .nes 文件的解析器、一颗周期精确的 6502、一条带镜像的总线、一枚点级推进的 PPU(背景流水线、精灵、sprite 0 hit)、一套帧时序与 NMI、一只手柄、一个 NROM 卡带接口,和一台在浏览器里跑真 ROM 的整机——约三千行 TypeScript(核心、测试与 demo 合计),每一行都被 102 个单元断言与十几张真实测试卡带检验过。</p><p>比代码更值钱的是方法:先按硬件边界切模块,总线注入、委托留缝;先跑通再谈精度,每一步都有机械验证;遇到怪癖,查资料原样复现而不是按直觉「修正」。这些方法不挑题材——你的下一台模拟器(GB?CHIP-8?某台街机基板?)会因此快得多。</p><h3 id="章末地图" tabindex="-1">章末地图 <a class="header-anchor" href="#章末地图" aria-label="Permalink to &quot;章末地图&quot;">​</a></h3><ul><li><a href="./../README.html">课程 README</a>——demo 启动命令、测试卡带复跑方式</li><li><a href="./09-frame-timing.html">帧时序:NMI 与主循环</a>——四张失败卡带的初次登场</li></ul>',20)])])}const m=e(o,[["render",s]]);export{u as __pageData,m as default};
